import numpy as np

N = 39
# Formula: A[i, j] = (i + 2*j) mod 3
A = np.zeros((N, N), dtype=int)

for i in range(N):
    for j in range(N):
        A[i, j] = (i + 2 * j) % 3

# 1. Check Row Balance
row_counts = []
for i in range(N):
    counts = np.bincount(A[i, :], minlength=3)
    row_counts.append(counts)

print("--- Row Counts (Expected: [13, 13, 13]) ---")
print(f"Row 0 counts: {row_counts[0]}")
print(f"Row 1 count sum: {sum(row_counts[1])}")

# 2. Check Column Balance
col_counts = []
for j in range(N):
    counts = np.bincount(A[:, j], minlength=3)
    col_counts.append(counts)

print("\n--- Column Counts (Expected: [13, 13, 13]) ---")
print(f"Column 0 counts: {col_counts[0]}")
print(f"Column 1 count sum: {sum(col_counts[1])}")

# 3. Check Anti-Diagonal Balance (i+j = k)
anti_diag_counts = {}
for k in range(2 * N - 1):
    diag_elements = []
    # Elements (i, j) such that i + j = k
    for i in range(N):
        j = k - i
        if 0 <= j < N:
            diag_elements.append(A[i, j])

    length = len(diag_elements)
    if length >= 3 and length % 3 == 0:
        counts = np.bincount(diag_elements, minlength=3)
        # Check if balanced (count == length / 3)
        expected_count = length // 3
        if np.all(counts == expected_count):
            # Balanced
            pass
        else:
            # Not balanced (Failure)
            anti_diag_counts[k] = counts

print("\n--- Anti-Diagonal Check (Length multiple of 3) ---")
if anti_diag_counts:
    print("Found unbalanced anti-diagonals:")
    for k, counts in anti_diag_counts.items():
        print(f"Anti-diagonal k={k} (Length {len([A[i,k-i] for i in range(N) if 0 <= k-i < N])}): Counts {counts}")
else:
    print("All anti-diagonals of length multiple of 3 checked seem balanced (or none found).")

# 4. Check Main Diagonal Balance (i-j = k)
main_diag_counts = {}
for k in range(-(N - 1), N):
    diag_elements = []
    # Elements (i, j) such that i - j = k, so j = i - k
    for i in range(N):
        j = i - k
        if 0 <= j < N:
            diag_elements.append(A[i, j])

    length = len(diag_elements)
    if length >= 3 and length % 3 == 0:
        counts = np.bincount(diag_elements, minlength=3)
        expected_count = length // 3
        if np.all(counts == expected_count):
            # Balanced
            pass
        else:
            # Not balanced (Failure)
            main_diag_counts[k] = counts

print("\n--- Main Diagonal Check (Length multiple of 3) ---")
if main_diag_counts:
    print("Found unbalanced main diagonals:")
    for k, counts in main_diag_counts.items():
        print(f"Main diagonal k={k}: Counts {counts}")
else:
    print("All main diagonals of length multiple of 3 checked seem balanced (or none found).")
